import { DIET_CALORIES_RANGE, DIET_GOALS, DIET_MACRO_G_RANGE, DIET_WATER_ML_RANGE, MEAL_GEN_DIETS, MEAL_GEN_FOODS, MEAL_GEN_GOALS } from "../../domain/nutrition.js";
