  async function findTrainerIdWithPhone(sb, phone, excludeTrainerId) {
    const norm = normalizePhoneDigits(phone);
    if (!norm || !sb) return null;
    const { data, error } = await sb.from("trainers").select("id, phone").not("phone", "is", null);
    if (error || !data) return null; // can't verify right now — don't block a real signup/edit over a network blip
    const match = data.find((t) => t.id !== excludeTrainerId && normalizePhoneDigits(t.phone) === norm);
    return match ? match.id : null;
  }

  function shiftDateISO(iso, delta) {
    // Same local-timezone convention as dateToISO/todayISO — a plain
    // `.toISOString()` here silently skipped a day for anyone east of UTC
    // (Sept 18 2026 inspection: Beirut users tapping prev/next day landed
    // two days back instead of one).
    const d = new Date(iso + "T00:00:00");
    d.setDate(d.getDate() + delta);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 10);
  }

  function hourLabel12(h) {
    const period = h < 12 ? "AM" : "PM";
    const displayH = h % 12 === 0 ? 12 : h % 12;
    return `${displayH} ${period}`;
  }

  function DashboardStatGrid({ stats }) {
    const tiles = [
      { label: "Sessions today", value: String(stats.sessionsToday) },
      { label: "Sessions this month", value: String(stats.sessionsMonth) },
      { label: "Collected this month", value: `$${stats.monthPaid.toLocaleString()}` },
      { label: "Collected all-time", value: `$${stats.totalPaid.toLocaleString()}` }
    ];
    return e("div", { style: styles.dashGrid }, tiles.map((t) => e("div", { key: t.label, style: styles.dashTile },
      e("span", { style: styles.profileLabel }, t.label),
      e("span", { style: styles.dashTileValue }, t.value)
    )));
  }

  function readAndClearSignupDraft() {
    try {
      const raw = localStorage.getItem(SIGNUP_DRAFT_KEY);
      if (!raw) return null;
      localStorage.removeItem(SIGNUP_DRAFT_KEY);
      return JSON.parse(raw);
    } catch (err) { return null; }
  }

  function randomInviteCode() {
    const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // no 0/O/1/I to avoid confusion
    let out = "";
    for (let i = 0; i < 6; i++) out += chars[Math.floor(Math.random() * chars.length)];
    return out;
  }

  // Queue of pending diet-plan requests from any client who's tapped
  // "Request a diet plan" from their own Diet tab — previously the only way
  // to find these was to happen to open that exact client's page, which is
  // easy to miss entirely for a self-train client with no trainer to notice
  // it on their behalf. Centralized here the same way trainer requests are.
  const DIET_REQUEST_TABS = [
    { value: "pending", label: "Awaiting payment" },
    { value: "paid", label: "Paid" }
  ];

  const PROGRAM_REQUEST_TABS = [
    { value: "pending", label: "Awaiting payment" },
    { value: "paid", label: "Paid" }
  ];

  // GitHub-contributions-style grid — one column per week, one 11px square per
  // day, shaded by that day's training volume. Deliberately reuses the app's
  // own brand hue at increasing opacity (single-hue sequential scale) rather
  // than introducing a new palette, so it reads as part of the same app.
  function monthLabelFor(iso) {
    const [y, m, d] = iso.split("-").map(Number);
    return new Date(y, m - 1, d).toLocaleDateString("en-US", { month: "short" });
  }

  const DIET_FIELD_MAP = { calories: "calories_target", protein: "protein_target", carbs: "carbs_target", fat: "fat_target", water: "water_target_ml" };

  function macroHit(actual, target, tolerancePct, floorOnly) {
    if (target == null || actual == null) return null;
    if (floorOnly) return actual >= target;
    const lo = target * (1 - tolerancePct);
    const hi = target * (1 + tolerancePct);
    return actual >= lo && actual <= hi;
  }

  // Per-macro status: how far actual intake is from target, and in which direction.
  function macroStatusInfo(actual, target, tolerancePct, floorOnly) {
    if (target == null || actual == null) return null;
    const diff = Math.round(actual - target);
    const hit = macroHit(actual, target, tolerancePct, floorOnly);
    if (hit) return { label: "On target", diff: 0, kind: "good" };
    if (diff > 0) return { label: `${diff} over`, diff, kind: "over" };
    return { label: `${Math.abs(diff)} under`, diff, kind: "under" };
  }

  function macroStatusColors(kind) {
    if (kind === "good") return { color: C.good, background: C.goodSoft };
    if (kind === "over") return { color: C.critical, background: C.criticalSoft };
    return { color: C.brand, background: C.brandSoft };
  }

  function macroDeltaTag(actual, target, tolerancePct, floorOnly) {
    const info = macroStatusInfo(actual, target, tolerancePct, floorOnly);
    if (!info) return null;
    return e("span", { style: { color: macroStatusColors(info.kind).color, fontWeight: 600 } }, ` (${info.label})`);
  }

  function defaultActivityKey(daysPerWeek) {
    const d = daysPerWeek || 3;
    if (d <= 1) return "sedentary";
    if (d <= 3) return "light";
    if (d <= 5) return "moderate";
    if (d <= 6) return "active";
    return "very_active";
  }

  // Structured, meal-by-meal plan builder — mirrors how training programs are
  // built (days -> exercises), just for meals -> food items instead. Each item
  // belongs to a meal_label (e.g. "Breakfast") within one client's diet_plans row.
  const BLANK_MEAL_ITEM_FORM = { mealLabel: "", foodItem: "", portion: "", calories: "", protein: "", carbs: "", fat: "", notes: "" };

  const BLANK_DIET_TEMPLATE_FORM = { name: "", description: "", calories: "", protein: "", carbs: "", fat: "", water: "" };

  // Sept 15 2026, Jimmy: "in the general resistance training can we
  // duplicate the weeks depends on the program duration so the client can
  // log the weight weekly not only for one week" — the shared catalog
  // library (ProgramsPanel/ClientProgramCard below) used to have no real
  // week concept at all, just day_label text, so a 12-week program was
  // really just one repeating "Week 1" template with no way to tell weeks
  // apart. program_exercises now has its own week_label column (same idea
  // client_program_items already had for a trainer's hand-written client
  // programs) — these two helpers parse a "Week N" label back out to a
  // number (for finding the next one / the generation target) and are
  // shared by both components below. A row saved before this column
  // existed just reads back as week_label === null, treated as "Week 1"
  // everywhere it's grouped/duplicated — no backfill required for existing
  // programs to keep working exactly as they did.
  function parseWeekNumber(label) {
    const m = /^week\s+(\d+)$/i.exec(String(label || "").trim());
    return m ? parseInt(m[1], 10) : null;
  }

  function nextWeekLabel(existingLabels) {
    let max = 0;
    existingLabels.forEach((l) => { const n = parseWeekNumber(l); if (n && n > max) max = n; });
    return `Week ${max + 1}`;
  }

  // Parse what someone typed into that one field back into { sets, reps } for
  // storage. Accepts "3x8", "4 x 10-12", "3×8", etc. Anything that doesn't
  // look like "<number>x<rest>" is stored as reps only (sets left blank) so
  // free text like "AMRAP" or "to failure" still works.
  function parseSetsReps(text) {
    const trimmed = (text || "").trim();
    if (!trimmed) return { sets: null, reps: null };
    const match = trimmed.match(/^(\d+)\s*[x×]\s*(.+)$/i);
    if (match) return { sets: Number(match[1]), reps: match[2].trim() || null };
    return { sets: null, reps: trimmed };
  }

  // Fully editable — trainers build these programs themselves (create a program,
  // add days, add/edit/delete each exercise). The seeded programs are just a
  // starting point, not fixed content.
  function styleLabel(v) {
    const found = TRAINING_STYLES.find((s) => s.value === v);
    return found ? found.label : v;
  }

  // Faint, repeating overlay stamped over a client's program content so a
  // screenshot/photo of it carries the client's name — discourages a paid
  // program getting forwarded around for free, without blocking anything
  // (pointer-events: none) or hurting readability (very low opacity).
  function watermarkTileDataUri(label) {
    const safe = String(label)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
    const svg =
      "<svg xmlns='http://www.w3.org/2000/svg' width='230' height='130'>" +
      "<text x='115' y='72' transform='rotate(-28 115 65)' text-anchor='middle' " +
      "font-family='Arial, sans-serif' font-size='13' fill='rgba(140,150,175,0.5)'>" + safe + "</text>" +
      "</svg>";
    return "data:image/svg+xml," + encodeURIComponent(svg);
  }

  // Turns this form's structured per-set array into the compact legacy
  // summary columns (sets count, "8x10x10" reps text, "60x60x65" weight
  // text, one rest value) — kept as a fallback display/search surface for
  // any exercise saved before `sets_detail` existed. `sets_detail` (the new
  // jsonb column, same per-set shape as workout_entries.sets) is always the
  // source of truth for anything saved through this form now.
  function summarizeSetsDetail(sets, isTimed, isBodyweight) {
    const reps = sets.map((s) => (isTimed ? `${s.duration}s` : s.reps)).join("x");
    const weight = isBodyweight ? "Bodyweight" : sets.map((s) => (s.weight != null ? s.weight : "")).join("x");
    const rest = sets.length && sets[0].rest != null ? sets[0].rest : null;
    return { sets: sets.length, reps, weight, rest_seconds: rest };
  }

  async function submitPaymentClaim(email, context) {
    if (!sb || !email) return null;
    const { data } = await sb.from("payment_claims")
      .insert([{ payer_email: email.toLowerCase(), context }])
      .select().maybeSingle();
    return data || null;
  }

  // Sept 12 2026, Jimmy: "for each section his own logo related to programs
  // or levels its more fun" — a small colored icon badge per program, read
  // from its name (Beginner/Intermediate/Advanced) first and falling back to
  // its training style, so a stacked list of cards is visually distinct
  // instead of the same gray dumbbell square repeated down the page.
  function programVisual(name, style) {
    const n = (name || "").toLowerCase();
    if (/\b(beginner|foundation|starter|intro)\b/.test(n)) return { icon: "sparkle", color: C.good };
    if (/\b(intermediate|builder|progression)\b/.test(n)) return { icon: "trendUp", color: C.brand };
    if (/\b(advanced|elite|pro|master)\b/.test(n)) return { icon: "flame", color: C.critical };
    // Sept 15 2026, Jimmy: "do logo for every section here" — pointed at the
    // Programs list where the 5 circuit programs all share the
    // circuit_training style and so all fell through to the same "swap"
    // badge below, right back to the repeated-gray-box look the level check
    // above was built to fix. Name-match the specific circuit programs to
    // their own icon/color too, one level down from Beginner/Intermediate/
    // Advanced — same idea, just keyed off what's actually in the name.
    if (/\btotal body\b/.test(n)) return { icon: "activity", color: C.brand };
    if (/\bupper\s*\/?\s*lower\b/.test(n)) return { icon: "trendUp", color: C.clientAccent };
    if (/\bbodyweight\b/.test(n) || /\bat home\b/.test(n)) return { icon: "user", color: C.good };
    if (/\bcore\b/.test(n) || /\bconditioning\b/.test(n)) return { icon: "flame", color: C.warning };
    if (/\bstrength.endurance\b/.test(n) || /\bendurance\b/.test(n)) return { icon: "trophy", color: C.critical };
    const byStyle = { powerlifting: "dumbbell", calisthenics: "activity", hyrox: "clock", general_resistance: "dumbbell", circuit_training: "swap" };
    return { icon: byStyle[style] || "dumbbell", color: C.brand };
  }

